// ---------------------------------------------------------------------------
// CodeGenOptions — configures how JSX is lowered
// ---------------------------------------------------------------------------

enum class JSXPragma {
    React,      // React.createElement(...)  [default]
    H,          // h(...)                    [Preact / hyperscript]
    JSX,        // _jsx(...)                 [React 17 classic runtime alias]
    AutoImport, // React 17+ automatic runtime: import {jsx as _jsx} from 'react/jsx-runtime'
};

struct CodeGenOptions {
    JSXPragma pragma       = JSXPragma::React;
    bool      devMode      = false;   // emit __source / __self props
    bool      minify       = false;   // future: compact output
    int       indentWidth  = 2;

    // Pragma call as string: "React.createElement", "h", "_jsx", "_jsx"
    std::string pragmaCall() const {
        switch (pragma) {
            case JSXPragma::React:      return "React.createElement";
            case JSXPragma::H:          return "h";
            case JSXPragma::JSX:        return "_jsx";
            case JSXPragma::AutoImport: return "_jsx";
        }
        return "React.createElement";
    }

    // Fragment expression: "React.Fragment", "Fragment", etc.
    std::string fragmentExpr() const {
        switch (pragma) {
            case JSXPragma::React:      return "React.Fragment";
            case JSXPragma::H:          return "Fragment";
            case JSXPragma::JSX:        return "_Fragment";
            case JSXPragma::AutoImport: return "_Fragment";
        }
        return "React.Fragment";
