static ygg_allocator g_alloc = { malloc, free, realloc };

void ygg_set_allocator(const ygg_allocator& a) {
    g_alloc.alloc_fn   = a.alloc_fn   ? a.alloc_fn   : malloc;
    g_alloc.free_fn    = a.free_fn    ? a.free_fn    : free;
    g_alloc.realloc_fn = a.realloc_fn ? a.realloc_fn : realloc;
}

