/* yggdrasil_c_api.cpp
 *
 * Thin C shim over the C++ internals.  This is the only translation unit
 * that includes yggdrasil.h; all other .cpp files remain pure C++.
 *
 * Rules enforced here:
 *  - No C++ types cross the extern "C" boundary.
 *  - All exceptions are caught and converted to ygg_result error structs.
 *  - All heap use in returned structs goes through ygg_alloc / ygg_free.
 */

#include "yggdrasil.h"
#include "ygg_alloc.h"

#include "lexer.h"
#include "parser.h"
#include "codegen.h"
#include "diagnostics.h"
#include "batch.h"

#include <cstring>
#include <fstream>
#include <sstream>
#include <filesystem>

namespace fs = std::filesystem;

/* -------------------------------------------------------------------------
 * Internal helpers
 * ---------------------------------------------------------------------- */

static CodeGenOptions optsFromCfg(const ygg_config* cfg) {
    CodeGenOptions o;
    if (!cfg) return o;

    /* Map C pragma constant → internal enum */
    switch (cfg->pragma) {
        case YGG_PRAGMA_H:    o.pragma = JSXPragma::H;          break;
        case YGG_PRAGMA_JSX:  o.pragma = JSXPragma::JSX;        break;
        case YGG_PRAGMA_AUTO: o.pragma = JSXPragma::AutoImport; break;
        default:              o.pragma = JSXPragma::React;       break;
    }
    o.devMode = (cfg->dev_mode != 0);

    /* Install custom allocator if provided */
    if (cfg->alloc_fn || cfg->free_fn || cfg->realloc_fn) {
        ygg_allocator a{cfg->alloc_fn, cfg->free_fn, cfg->realloc_fn};
        ygg_set_allocator(a);
    }

    return o;
}

static ygg_result make_ok(const std::string& js) {
    ygg_result r{};
    r.ok     = 1;
    r.output = ygg_strdup(js.c_str());
    return r;
}

static ygg_result make_err(const char* msg, int line = 0, int col = 0) {
    ygg_result r{};
    r.ok         = 0;
    r.error_msg  = ygg_strdup(msg);
    r.error_line = line;
    r.error_col  = col;
    return r;
}

/* Core transpile: string in → string out.  Called by both string and file variants. */
static ygg_result transpile_source(const char* source,
                                   const CodeGenOptions& opts,
                                   const char* filename) {
    try {
        Lexer lexer(source);
        auto tokens = lexer.tokenize();

        Parser parser(std::move(tokens));
        auto ast = parser.parse();

        CodeGen gen(opts);
        std::string js = gen.generate(*ast, filename ? filename : "");

        return make_ok(js);

    } catch (const LexError& e) {
        return make_err(e.what(), e.line, e.col);
    } catch (const ParseError& e) {
        return make_err(e.what(), e.line, e.col);
    } catch (const CodeGenError& e) {
        return make_err(e.what());
    } catch (const std::exception& e) {
        return make_err(e.what());
    } catch (...) {
        return make_err("unknown internal error");
    }
}

/* -------------------------------------------------------------------------
 * Public API
 * ---------------------------------------------------------------------- */

extern "C" {

const char* yggdrasil_version_string(void) {
    return "1.0.0";
}

int yggdrasil_version_check(int major, int minor) {
    if (major != YGGDRASIL_VERSION_MAJOR) return 0;
    if (minor >  YGGDRASIL_VERSION_MINOR) return 0;
    return 1;
}

void yggdrasil_init(void) {
    /* Currently stateless — reserved for future thread-local pools etc. */
}

void yggdrasil_shutdown(void) {
    /* Reserved. */
}

ygg_result yggdrasil_transpile_string(const char* source,
                                      const ygg_config* cfg) {
    if (!source) return make_err("source must not be null");
    CodeGenOptions opts = optsFromCfg(cfg);
    return transpile_source(source, opts, nullptr);
}

ygg_result yggdrasil_transpile_file(const char* input_path,
                                    const ygg_config* cfg) {
    if (!input_path) return make_err("input_path must not be null");

    std::ifstream f(input_path);
    if (!f) {
        std::string msg = std::string("cannot open '") + input_path + "'";
        return make_err(msg.c_str());
    }
    std::ostringstream ss;
    ss << f.rdbuf();

    CodeGenOptions opts = optsFromCfg(cfg);
    return transpile_source(ss.str().c_str(), opts, input_path);
}

int yggdrasil_transpile_dir(const char* src_dir,
                             const char* out_dir,
                             const ygg_config* cfg) {
    if (!src_dir || !out_dir) return -1;

    std::error_code ec;
    fs::create_directories(out_dir, ec);
    if (ec) return -1;

    BatchOptions bopts;
    bopts.srcDir      = src_dir;
    bopts.outDir      = out_dir;
    bopts.codegenOpts = optsFromCfg(cfg);
    bopts.verbose     = false;
    bopts.noCopy      = false;

    BatchEngine engine(bopts);
    BatchResult r = engine.run();
    return r.failed;
}

void ygg_result_free(ygg_result* r) {
    if (!r) return;
    ygg_free(r->output);
    ygg_free(r->error_msg);
    r->output    = nullptr;
    r->error_msg = nullptr;
}

} /* extern "C" */

