                            const ygg_config& cfg) {
    ygg_result r = yggdrasil_transpile_file(inputPath.c_str(), &cfg);

    if (!r.ok) {
        if (r.error_line > 0)
            std::cerr << inputPath << ":" << r.error_line << ":" << r.error_col
