    // -----------------------------------------------------------------------
    // Determine run mode
    // -----------------------------------------------------------------------

    // Check if the first positional is a directory
    bool firstIsDir = fs::is_directory(positional[0]);

    bool batchMode = !outDir.empty() || firstIsDir;

    if (!batchMode) {
        // ---- Single-file mode ----
        if (positional.size() > 1) {
            std::cerr << "error: multiple input files require --out-dir\n";
            return 1;
        }
        if (watchMode) {
            std::cerr << "error: --watch requires a source directory\n";
            return 1;
        }
        return transpileSingle(positional[0], outputPath, copts, recoverMode) ? 0 : 1;
    }

