        std::cout << "\n";
        if (bopts.verbose || r.failed > 0) {
            std::cout << "  transpiled : " << r.transpiled << "\n";
            if (!bopts.noCopy)
                std::cout << "  copied     : " << r.copied << "\n";
            if (r.skipped > 0)
                std::cout << "  skipped    : " << r.skipped << "\n";
            if (r.failed > 0) {
                std::cout << "  failed     : " << r.failed << "\n";
                for (const auto& e : r.errors)
                    std::cerr << e.message << "\n";
            }
        }

        if (watchMode) {
            Watcher watcher(engine, bopts.verbose);
            g_watcher = &watcher;
            std::signal(SIGINT,  handleSignal);
            std::signal(SIGTERM, handleSignal);
            watcher.watch(bopts.srcDir);
            g_watcher = nullptr;
        }

        return r.ok() ? 0 : 1;

    } else {
        // Explicit file list with --out-dir
        int failures = 0;

        // Derive a synthetic srcDir as the common parent of all inputs
        // (used only for output path computation)
        fs::path srcDir = fs::path(positional[0]).parent_path();
        bopts.srcDir    = srcDir;
        BatchEngine engine(bopts);

        for (const auto& inp : positional) {
            BatchResult r;
            engine.processFile(fs::path(inp), r);
            for (const auto& e : r.errors) std::cerr << e.message << "\n";
            failures += r.failed;
        }

        if (watchMode) {
            Watcher watcher(engine, bopts.verbose);
            g_watcher = &watcher;
            std::signal(SIGINT,  handleSignal);
            std::signal(SIGTERM, handleSignal);
            watcher.watch(srcDir);
            g_watcher = nullptr;
        }

        return failures > 0 ? 1 : 0;
    }
